examples.code:
function double(value: number): number {
  return value * 2;
}
console.log(double(21));

interface User {
  name: string;
}
const value: User = { name: "Ada" };
console.log(value.name);

type Identifier = string | number;
const value: Identifier = 42;
console.log(value);

type Result = string | number;
const value: Result = "ready";
console.log(value);

function describe(value: string | number): string {
  if (typeof value === "string") return value.toUpperCase();
  return value.toFixed(2);
}
console.log(describe(42));

function identity<T>(value: T): T {
  return value;
}
const result = identity<string>("typed");
console.log(result);

interface Configuration {
  readonly mode: string;
}
const value: Configuration = { mode: "safe" };
console.log(value.mode);

interface User {
  nickname?: string;
}
const user: User = {};
console.log(user.nickname?.toUpperCase() ?? "No nickname");

type Result =
  | { kind: "success"; value: number }
  | { kind: "error"; message: string };
function summarize(result: Result): string {
  return result.kind === "success" ? `Value: ${result.value}` : `Error: ${result.message}`;
}
const result: Result = { kind: "success", value: 42 };
console.log(summarize(result));

interface Named {
  name: string;
}
class Person implements Named {
  name: string;
  constructor(name: string) {
    this.name = name;
  }
  describe(): string {
    return this.name;
  }
}
console.log(new Person("Ada").describe());

type Channel = "stable" | "preview";
const config = { channel: "stable", retries: 3 } satisfies { channel: Channel; retries: number };
console.log(config.channel);

function getProperty<T, K extends keyof T>(object: T, key: K): T[K] {
  return object[key];
}
const settings = { theme: "dark", fontSize: 16 };
console.log(getProperty(settings, "theme"));

async function resolveValue(value: number): Promise<number> {
  return value;
}
(async (): Promise<void> => {
  const value: number = await resolveValue(42);
  console.log(value);
})()

type Identified = { id: number } & { name: string };
const value: Identified = { id: 42, name: "Ada" };
console.log(value.name);

type Direction = "left" | "right";
const value: Direction = "left";
console.log(value);

type Coordinate = [x: number, y: number];
const point: Coordinate = [10, 20];
console.log(point[0] + point[1]);

type Pair = readonly [string, number];
const pair: Pair = ["age", 42];
console.log(pair[1]);

function measure<T extends { length: number }>(value: T): number {
  return value.length;
}
console.log(measure("typed"));

type Container<T = string> = { value: T };
const value: Container = { value: "ready" };
console.log(value.value);

type User = { id: number; name: string };
type UserId = User["id"];
const value: UserId = 42;
console.log(value);

const defaults = { retries: 3, mode: "safe" };
type Configuration = typeof defaults;
const value: Configuration = { retries: 1, mode: "fast" };
console.log(value.mode);

type Label<T> = T extends string ? "text" : "other";
const value: Label<string> = "text";
console.log(value);

function createValue() { return { id: 42 }; }
type ResultOf<T> = T extends (...args: never[]) => infer R ? R : never;
type Result = ResultOf<typeof createValue>;
const value: Result = createValue();
console.log(value.id);

type Promised<T> = { [K in keyof T]: Promise<T[K]> };
type Result = Promised<{ id: number }>;
const value: Result = { id: Promise.resolve(42) };
void value.id.then(result => console.log(result));

type Getters<T> = { [K in keyof T as `get${Capitalize<string & K>}`]: T[K] };
type Result = Getters<{ name: string }>;
const value: Result = { getName: "Ada" };
console.log(value.getName);

type Field = "name" | "age";
type EventName = `on${Capitalize<Field>}Changed`;
const value: EventName = "onNameChanged";
console.log(value);

function isString(value: unknown): value is string {
  return typeof value === "string";
}
const value: unknown = "typed";
if (isString(value)) console.log(value.toUpperCase());

function assertString(value: unknown): asserts value is string {
  if (typeof value !== "string") throw new TypeError("Expected text");
}
const value: unknown = "typed";
assertString(value);
console.log(value.toUpperCase());

type Value = { path: string } | { url: string };
function describe(value: Value): string {
  if ("path" in value) return value.path;
  return value.url;
}
console.log(describe({ path: "index.ts" }));

const value: Date | string = new Date(0);
if (value instanceof Date) console.log(value.toISOString());
else console.log(value.toUpperCase());

type State = "ready" | "done";
function describe(state: State): string {
  switch (state) {
    case "ready": return "Ready";
    case "done": return "Done";
    default: { const unreachable: never = state; return unreachable; }
  }
}
console.log(describe("ready"));

function normalize(value: string): string;
function normalize(value: number): number;
function normalize(value: string | number): string | number { return value; }
console.log(normalize("ready"));

interface Formatter { (value: string): string; label: string; }
const formatter = ((value: string) => value.toUpperCase()) as Formatter;
formatter.label = "upper";
console.log(formatter("typed"), formatter.label);

interface CreatesItem { new (name: string): Item; }
class Item { name: string; constructor(name: string) { this.name = name; } }
function create(ctor: CreatesItem, value: string): Item { return new ctor(value); }
console.log(create(Item, "typed").name);

interface Scores { [name: string]: number; }
const scores: Scores = { alpha: 10, beta: 20 };
console.log(scores["beta"]);

interface Dimensions { width: number; }
interface Dimensions { height: number; }
const value: Dimensions = { width: 10, height: 20 };
console.log(value.width * value.height);

interface Box<T> { value: T; }
const value: Box<number> = { value: 42 };
console.log(value.value);

interface Counter { value: number; }
function read(this: Counter): number { return this.value; }
console.log(read.call({ value: 42 }));

function greet(name?: string): string {
  return `Hello, ${name ?? "there"}`;
}
console.log(greet("Ada"));

function format(...args: [label: string, value: number]): string {
  return `${args[0]}: ${args[1]}`;
}
console.log(format("Answer", 42));

function concat<A extends unknown[], B extends unknown[]>(left: [...A], right: [...B]): [...A, ...B] {
  return [...left, ...right];
}
const value = concat(["answer", 42], [true]);
console.log(value);

type UserId = number & { readonly __brand: "UserId" };
function createUserId(value: number): UserId { return value as UserId; }
const value = createUserId(42);
console.log(value);
